"""Stage C6: decomposition of Bolmo all-int4 time per generated byte, from the Stage C measurements.

Inputs (all in results/fair): nsys/all-int4-analysis.json (kernel counts/times per graph, from the nsys
trace), sync_cost.json (untraced GPU time per graph replay, sync cost), node_floor.json (cost per trivial
graph node), s-bolmo-all-int4-r{1,2} (speed runs). Everything is normalized to the bytes per patch of the
speed runs, not of the traced prompt.
Run: python -X utf8 tools/floor_decomposition.py [bytes_per_patch=3.38]
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

R = Path("results/fair")


def speed_mean(name: str) -> float:
    vals = []
    for rep in (1, 2):
        d = sorted(p for p in (R / f"s-bolmo-{name}-r{rep}").glob("2*") if p.is_dir())[-1]
        rows = json.loads((d / "breakdown.json").read_text(encoding="utf-8"))["rows"]
        vals.append(sum(r["ms"] for r in rows) / sum(r["new_bytes"] for r in rows))
    return sum(vals) / 2


def main() -> None:
    bpp = float(sys.argv[1]) if len(sys.argv) > 1 else 3.38
    a = json.loads((R / "nsys/all-int4-analysis.json").read_text(encoding="utf-8"))
    sc = json.loads((R / "sync_cost.json").read_text(encoding="utf-8"))["graphs"]
    nf = json.loads((R / "node_floor.json").read_text(encoding="utf-8"))["rows"]
    g = a["per_graph"]
    # share of byte windows that are boundary (dec_p) steps vs not, from the trace; per byte one enc + one dec
    n_n, n_p = g["dec_n"]["windows"], g["dec_p"]["windows"]
    w_dec = {k: g[k] for k in ("dec_n", "dec_p")}

    def dec(field: str) -> float:
        return (g["dec_n"][field] * n_n + g["dec_p"][field] * n_p) / (n_n + n_p)

    per_byte = {}
    for field in ("kernels", "kernel_us", "gemm_kernels", "gemm_us", "short_kernels", "short_us"):
        per_byte[field] = g["enc_m"][field] + dec(field) + g["glob"][field] / bpp
    replay_us = sc["enc_m"]["2"]["gpu_event_us"] + (sc["dec_n"]["2"]["gpu_event_us"] * (1 - 1 / bpp)
                                                   + sc["dec_p"]["2"]["gpu_event_us"] / bpp) + sc["glob"]["2"]["gpu_event_us"] / bpp
    sync_us = sc["dec_n"]["2"]["sync_cost_us"]  # one sync per byte
    sync_min = min(r["sync_cost_us"] for r in sc["dec_n"].values())
    node_us = sum(r["us_per_node"] for r in nf) / len(nf)
    total = speed_mean("all-int4") * 1000
    gemm, nongemm = per_byte["gemm_us"], per_byte["kernel_us"] - per_byte["gemm_us"]
    ingraph_gaps = replay_us - per_byte["kernel_us"]
    outside = total - replay_us
    state_bytes = 5 * (1 * 16 * 128 * 128 * 4 + 1 * 16 * 128 * 4 + 1 * 16 * 1 * 4)  # c, n, m of 5 layers, fp32
    traffic = state_bytes * 4  # step kernel reads + writes new state, in-graph copy_ reads + writes it back
    print(f"## Decomposition of Bolmo all-int4, ms per generated byte (speed runs: {total / 1000:.3f}; bytes/patch {bpp})\n")
    print("| component | us/byte | share of speed-run time | source |\n|---|---:|---:|---|")
    rows = [
        ("matmul kernels (tinygemm), weight-proportional", gemm, "nsys trace, per graph, weighted by launches/byte"),
        ("all other kernels (norms, elementwise, rotary, attention, mLSTM step, copies as kernels)", nongemm, "nsys trace"),
        ("gaps between kernels inside graph replays", ingraph_gaps, "untraced replay GPU time (CUDA events) minus kernel sum"),
        ("outside replays: sync + D2H copy, host loop, launches, prefill share", outside,
         f"speed-run time minus replay time (sync check alone: {sync_us:.0f} us, min {sync_min:.0f})"),
    ]
    for name, v, src in rows:
        print(f"| {name} | {v:.0f} | {v / total * 100:.0f}% | {src} |")
    print(f"| **total** | {total:.0f} | 100% | |")
    print(f"\nkernels per byte: {per_byte['kernels']:.0f} (matmul {per_byte['gemm_kernels']:.0f}, "
          f"short < 10 us: {per_byte['short_kernels']:.0f}, taking {per_byte['short_us']:.0f} us); "
          f"enc {g['enc_m']['kernels']:.0f}, dec {dec('kernels'):.0f}, glob {g['glob']['kernels']:.0f} per patch.")
    print(f"node floor (trivial kernel in a graph): {node_us:.2f} us -> {per_byte['kernels'] * node_us:.0f} us "
          f"for {per_byte['kernels']:.0f} kernels")
    print(f"H20 quantities: short kernels {per_byte['short_us']:.0f} us + in-graph gaps {ingraph_gaps:.0f} us = "
          f"{per_byte['short_us'] + ingraph_gaps:.0f} us (threshold 600); sync+D2H {sync_us:.0f} us (threshold 300); "
          f"state traffic {traffic / 1e6:.1f} MB/byte = {traffic / 448e9 * 1e6:.0f} us at 448 GB/s, "
          f"{traffic / 342e9 * 1e6:.0f} us at 342 GB/s (best bf16 kernel), {traffic / 300e9 * 1e6:.0f} us at 300 GB/s "
          f"(threshold 100)")
    print(f"non-matmul total (fixed part): {nongemm + ingraph_gaps + outside:.0f} us per byte")


if __name__ == "__main__":
    main()
